import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TextGlitchTrigger = "always" | "hover";

export interface TextGlitchProps {
  /** The string to render. */
  text: string;
  /** Tag rendered as the outer element. */
  as?: keyof React.JSX.IntrinsicElements;
  /**
   * Base glitch cycle duration in seconds. Lower = more frantic.
   * Channel layers desync automatically (×1 / ×1.4). Default: 2.4
   */
  duration?: number;
  /** Horizontal slice offset in CSS pixels. Default: 5 */
  offset?: number;
  /** Chromatic aberration text-shadows on the slice layers. Default: true */
  enableShadows?: boolean;
  /** Left-channel shadow color (typically cool). Theme cyan by default. */
  leftColor?: string;
  /** Right-channel shadow color (typically warm). Theme rose by default. */
  rightColor?: string;
  /**
   * Opaque mask behind each slice so offset bands don't ghost the base
   * glyph. Omit for theme surface (`#fafafa` / `#0a0a0b`).
   */
  surfaceColor?: string;
  /** When to run the loop. Default: `"always"`. */
  trigger?: TextGlitchTrigger;
  /**
   * Force the loop paused. When omitted, auto-pauses off-screen or when
   * the tab is hidden (always-mode only).
   */
  paused?: boolean;
  /** Optional Tailwind class for size, weight, tracking, etc. */
  className?: string;
}

const BASE_STYLE_ID = "wensity-text-glitch-base";

/**
 * TextGlitch
 *
 * Chromatic clip-path glitch for React headlines. One element — two
 * pseudo-layers carry the RGB split + horizontal band slicing. No Motion,
 * no per-character DOM, no Tailwind animation config.
 *
 * Motion contract:
 * - CSS `linear infinite` on ::before / ::after with desynced durations.
 * - Animates `clip-path` + `transform` (clip-path paints; transform is cheap).
 * - Auto-pauses off-screen / hidden tabs via `animation-play-state`.
 * - `trigger="hover"` keeps layers dormant until pointer enter.
 * - Honours `prefers-reduced-motion` with a static headline.
 */
export function TextGlitch({
  text,
  as = "span",
  duration = 2.4,
  offset = 5,
  enableShadows = true,
  leftColor,
  rightColor,
  surfaceColor,
  trigger = "always",
  paused,
  className,
}: TextGlitchProps) {
  const nodeRef = React.useRef<HTMLElement | null>(null);
  const pausedPropRef = React.useRef(paused);
  const inViewRef = React.useRef(true);
  pausedPropRef.current = paused;

  const safeDuration = Math.max(0.4, duration);
  const safeOffset = Math.max(0, Math.min(24, offset));

  React.useLayoutEffect(() => {
    ensureBaseStyles();
  }, []);

  React.useEffect(() => {
    const node = nodeRef.current;
    if (!node) return;

    // Hover-only mode is CSS-driven; skip observers to avoid work.
    if (trigger === "hover") {
      node.dataset.glitchPaused = paused === true ? "true" : "false";
      return;
    }

    let pageVisible = document.visibilityState !== "hidden";

    const syncPlayState = () => {
      const forced = pausedPropRef.current;
      const autoPause = !(inViewRef.current && pageVisible);
      const shouldPause =
        forced === true || (forced !== false && autoPause);
      node.dataset.glitchPaused = shouldPause ? "true" : "false";
    };

    if (paused === true) {
      syncPlayState();
      return;
    }

    const io = new IntersectionObserver(
      (entries) => {
        inViewRef.current = entries.some((entry) => entry.isIntersecting);
        syncPlayState();
      },
      { threshold: 0.01 },
    );

    const onVisibility = () => {
      pageVisible = document.visibilityState !== "hidden";
      syncPlayState();
    };

    if (paused !== false) {
      io.observe(node);
      document.addEventListener("visibilitychange", onVisibility);
    }

    syncPlayState();

    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [paused, trigger]);

  const Tag = as as unknown as React.ComponentType<
    React.HTMLAttributes<HTMLElement> & {
      ref?: React.RefCallback<HTMLElement | null>;
      "data-text"?: string;
      "data-glitch-paused"?: "true" | "false";
      "data-glitch-trigger"?: TextGlitchTrigger;
      "data-glitch-shadows"?: "true" | "false";
    }
  >;

  return (
    <Tag
      ref={(node) => {
        nodeRef.current = node;
      }}
      data-text={text}
      data-glitch-paused={paused === true ? "true" : "false"}
      data-glitch-trigger={trigger}
      data-glitch-shadows={enableShadows ? "true" : "false"}
      className={cn(
        "wensity-text-glitch relative inline-block select-none",
        "[transform:translateZ(0)] [text-wrap:balance]",
        // Theme-aware surface mask + chromatic defaults.
        "[--wensity-glitch-surface:#fafafa] dark:[--wensity-glitch-surface:#0a0a0b]",
        "[--wensity-glitch-left:#22d3ee] [--wensity-glitch-right:#f43f5e]",
        className,
      )}
      style={
        {
          "--wensity-glitch-duration": `${safeDuration}s`,
          "--wensity-glitch-duration-alt": `${safeDuration * 1.4}s`,
          "--wensity-glitch-offset": `${safeOffset}px`,
          ...(leftColor ? { "--wensity-glitch-left": leftColor } : null),
          ...(rightColor ? { "--wensity-glitch-right": rightColor } : null),
          ...(surfaceColor
            ? { "--wensity-glitch-surface": surfaceColor }
            : null),
        } as React.CSSProperties
      }
    >
      {text}
    </Tag>
  );
}

function ensureBaseStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(BASE_STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = BASE_STYLE_ID;
  style.textContent = BASE_STYLES;
  document.head.appendChild(style);
}

/**
 * Compact slice keyframes — enough irregularity for a VHS read, without the
 * 20-stop redundant tables common in demos. Alternate channel uses a
 * mirrored transform so the RGB split never locks in phase.
 */
const BASE_STYLES = `
.wensity-text-glitch {
  isolation: isolate;
  contain: paint;
}
.wensity-text-glitch::before,
.wensity-text-glitch::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--wensity-glitch-surface);
  pointer-events: none;
  /* No permanent will-change — infinite clip-path already paints; promoting
     layers forever costs GPU memory across many instances. */
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-direction: alternate-reverse;
  animation-fill-mode: both;
  animation-play-state: running;
}
.wensity-text-glitch::before {
  left: calc(var(--wensity-glitch-offset, 5px) * -1);
  text-shadow: none;
  animation-name: wensity-text-glitch-a;
  animation-duration: var(--wensity-glitch-duration, 2.4s);
  clip-path: inset(0 0 85% 0);
}
.wensity-text-glitch::after {
  left: var(--wensity-glitch-offset, 5px);
  text-shadow: none;
  animation-name: wensity-text-glitch-b;
  animation-duration: var(--wensity-glitch-duration-alt, 3.36s);
  clip-path: inset(85% 0 0 0);
}
.wensity-text-glitch[data-glitch-shadows="true"]::before {
  text-shadow: calc(var(--wensity-glitch-offset, 5px) * -0.35) 0 var(--wensity-glitch-left);
}
.wensity-text-glitch[data-glitch-shadows="true"]::after {
  text-shadow: calc(var(--wensity-glitch-offset, 5px) * 0.35) 0 var(--wensity-glitch-right);
}

/* Hover-gated: drop content + animation until pointer / keyboard focus. */
.wensity-text-glitch[data-glitch-trigger="hover"]::before,
.wensity-text-glitch[data-glitch-trigger="hover"]::after {
  content: none;
  animation: none;
}
.wensity-text-glitch[data-glitch-trigger="hover"]:where(:hover, :focus-visible)::before {
  content: attr(data-text);
  animation-name: wensity-text-glitch-a;
  animation-duration: var(--wensity-glitch-duration, 2.4s);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-direction: alternate-reverse;
}
.wensity-text-glitch[data-glitch-trigger="hover"]:where(:hover, :focus-visible)::after {
  content: attr(data-text);
  animation-name: wensity-text-glitch-b;
  animation-duration: var(--wensity-glitch-duration-alt, 3.36s);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-direction: alternate-reverse;
}
.wensity-text-glitch[data-glitch-trigger="hover"][data-glitch-shadows="true"]:where(:hover, :focus-visible)::before {
  text-shadow: calc(var(--wensity-glitch-offset, 5px) * -0.35) 0 var(--wensity-glitch-left);
}
.wensity-text-glitch[data-glitch-trigger="hover"][data-glitch-shadows="true"]:where(:hover, :focus-visible)::after {
  text-shadow: calc(var(--wensity-glitch-offset, 5px) * 0.35) 0 var(--wensity-glitch-right);
}

.wensity-text-glitch[data-glitch-paused="true"]::before,
.wensity-text-glitch[data-glitch-paused="true"]::after {
  animation-play-state: paused;
}

@keyframes wensity-text-glitch-a {
  0%   { clip-path: inset(18% 0 62% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.2), 0, 0); }
  12%  { clip-path: inset(8% 0 55% 0);  transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.6), 0, 0); }
  24%  { clip-path: inset(42% 0 28% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.9), 0, 0); }
  36%  { clip-path: inset(2% 0 78% 0);  transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.3), 0, 0); }
  48%  { clip-path: inset(55% 0 12% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.5), 0, 0); }
  62%  { clip-path: inset(28% 0 40% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.8), 0, 0); }
  76%  { clip-path: inset(70% 0 5% 0);  transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.35), 0, 0); }
  88%  { clip-path: inset(12% 0 48% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.45), 0, 0); }
  100% { clip-path: inset(35% 0 30% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.15), 0, 0); }
}
@keyframes wensity-text-glitch-b {
  0%   { clip-path: inset(62% 0 10% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.25), 0, 0); }
  14%  { clip-path: inset(20% 0 50% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.7), 0, 0); }
  28%  { clip-path: inset(5% 0 72% 0);  transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.55), 0, 0); }
  42%  { clip-path: inset(48% 0 18% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.4), 0, 0); }
  56%  { clip-path: inset(75% 0 2% 0);  transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.9), 0, 0); }
  70%  { clip-path: inset(15% 0 45% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.6), 0, 0); }
  84%  { clip-path: inset(38% 0 35% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * -0.2), 0, 0); }
  100% { clip-path: inset(58% 0 15% 0); transform: translate3d(calc(var(--wensity-glitch-offset, 5px) * 0.3), 0, 0); }
}

@media (prefers-reduced-motion: reduce) {
  .wensity-text-glitch::before,
  .wensity-text-glitch::after {
    content: none !important;
    animation: none !important;
    display: none !important;
  }
}
`;
